-- texte → date
SELECT TO_DATE('25/12/2025', 'DD/MM/YYYY') FROM dual;

-- date → texte
SELECT TO_CHAR(SYSDATE, 'DD/MM/YYYY') FROM dual;

SELECT TO_CHAR(DATE '2025-03-05', 'DD MONTH YYYY')  AS sans_fm,
       TO_CHAR(DATE '2025-03-05', 'fmDD Month YYYY') AS avec_fm
FROM   dual;

SELECT TO_CHAR(DATE '2025-03-05', 'fmDay DD Month YYYY',
                 'NLS_DATE_LANGUAGE=FRENCH') AS en_francais
FROM   dual;

SELECT ADD_MONTHS(DATE '2025-01-15', 3)  AS a,   -- 15/04/2025
       ADD_MONTHS(DATE '2023-01-31', 1)  AS b    -- 28/02/2023 (fin de mois)
FROM   dual;

SELECT MONTHS_BETWEEN(DATE '2025-07-15', DATE '2025-01-15') AS m1,   -- 6
       MONTHS_BETWEEN(DATE '2025-07-01', DATE '2025-01-15') AS m2    -- ≈ 5,55
FROM   dual;

SELECT id, date_cmd
FROM   commandes
WHERE  date_cmd BETWEEN DATE '2025-04-01' AND DATE '2025-04-30';

SELECT nom,
       TRUNC(MONTHS_BETWEEN(DATE '2026-01-01', date_embauche) / 12) AS anciennete
FROM   employes;
